parameters.jsCode:
// Parse Claude's JSON output and shape the response.
const raw = items[0].json.content?.[0]?.text || '{}';
let parsed;
try {
  parsed = JSON.parse(raw);
} catch (e) {
  // Attempt to extract a JSON block if Claude wrapped its output
  const match = raw.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : { objections: [] };
}
const asin = $('Webhook').first().json.body.asin;
return [{ json: { asin, objections: parsed.objections || [] } }];
